package com.bank.patterns.eventsourcing;

import java.math.BigDecimal;

// Immutable event: once appended, never changed. The Value Object is a record.
public record AccountEvent(String accountId, String type, BigDecimal amount) {
    public static AccountEvent debited(String id, BigDecimal amt) {
        return new AccountEvent(id, "DEBITED", amt);
    }
    public static AccountEvent credited(String id, BigDecimal amt) {
        return new AccountEvent(id, "CREDITED", amt);
    }
}
