package com.bank.patterns.eventsourcing;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Append-only event log. Balance is REBUILT by replaying events.
public class AccountEventStore {
    private static final Logger log = Logger.getLogger(AccountEventStore.class.getName());
    private final List<AccountEvent> events = new ArrayList<>();

    public void append(AccountEvent event) {
        events.add(event);
        log.info(() -> "Appended " + event.type() + " " + event.amount()
                     + " for " + event.accountId());
    }

    public BigDecimal replayBalance(String accountId, BigDecimal opening) {
        BigDecimal balance = opening;
        for (AccountEvent e : events) {
            if (!e.accountId().equals(accountId)) continue;
            if (e.type().equals("DEBITED")) balance = balance.subtract(e.amount());
            else balance = balance.add(e.amount());
        }
        return balance;
    }

    public List<AccountEvent> eventsFor(String accountId) {
        List<AccountEvent> result = new ArrayList<>();
        for (AccountEvent e : events) if (e.accountId().equals(accountId)) result.add(e);
        return result;
    }
}
