package com.bank.patterns.cqrs;

import com.bank.patterns.eventsourcing.AccountEvent;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

// CQRS read model: updated from events, answers "what is the balance?" instantly.
public class BalanceProjection {
    private final Map<String, BigDecimal> view = new HashMap<>();

    public void seed(String accountId, BigDecimal opening) { view.put(accountId, opening); }

    public void apply(AccountEvent e) {
        BigDecimal current = view.getOrDefault(e.accountId(), BigDecimal.ZERO);
        if (e.type().equals("DEBITED")) view.put(e.accountId(), current.subtract(e.amount()));
        else view.put(e.accountId(), current.add(e.amount()));
    }

    public BigDecimal balanceOf(String accountId) {
        return view.getOrDefault(accountId, BigDecimal.ZERO);
    }
}
