package com.bank.patterns.bulkhead;

import java.util.concurrent.Semaphore;
import java.util.logging.Logger;

// Bulkhead: cap concurrency per operation type so a loan surge
// cannot starve the threads that transfers need.
public class BulkheadExecutor {
    private static final Logger log = Logger.getLogger(BulkheadExecutor.class.getName());
    private final Semaphore permits;
    private final String name;

    public BulkheadExecutor(String name, int maxConcurrent) {
        this.name = name;
        this.permits = new Semaphore(maxConcurrent);
    }

    public boolean tryRun(Runnable task) {
        if (!permits.tryAcquire()) {
            log.warning(() -> "Bulkhead " + name + " full — rejecting to protect others");
            return false;
        }
        try { task.run(); return true; }
        finally { permits.release(); }
    }
}
