package com.bank.patterns;

import com.bank.patterns.bulkhead.BulkheadExecutor;
import com.bank.patterns.cqrs.BalanceProjection;
import com.bank.patterns.eventsourcing.AccountEvent;
import com.bank.patterns.eventsourcing.AccountEventStore;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class PatternsDemo {
    private static final Logger log = Logger.getLogger(PatternsDemo.class.getName());

    public static void main(String[] args) {
        AccountEventStore store = new AccountEventStore();
        BalanceProjection projection = new BalanceProjection();
        BigDecimal opening = new BigDecimal("1000000");
        projection.seed("SAV2001", opening);

        log.info("=== Event Sourcing: append debit + credit for Rajesh ===");
        AccountEvent d = AccountEvent.debited("SAV2001", new BigDecimal("50000"));
        AccountEvent c = AccountEvent.credited("SAV2001", new BigDecimal("20000"));
        store.append(d); projection.apply(d);
        store.append(c); projection.apply(c);

        log.info("Replayed balance = " + store.replayBalance("SAV2001", opening));
        log.info("CQRS read model balance = " + projection.balanceOf("SAV2001"));

        log.info("=== Bulkhead: transfers isolated from a loan surge ===");
        BulkheadExecutor transfers = new BulkheadExecutor("transfers", 2);
        for (int i = 1; i <= 3; i++) {
            final int n = i;
            boolean ran = transfers.tryRun(() ->
                log.info("Processing transfer #" + n));
            if (!ran) log.warning("Transfer #" + n + " shed to protect the pool");
        }
    }
}
